+package gateway
+
+import (
+	"net/http"
+
+	"lsd-author/internal/metrics"
+)
+
+// HTTPErrorResponses counts every 4xx and 5xx response served by the gateway.
+var HTTPErrorResponses = metrics.NewCounter(
+	"gateway_http_errors_total",
+	"4xx and 5xx responses served by the gateway",
+)
+
+// RecordHTTPResponse increments gateway error metrics for 4xx and 5xx statuses.
+func RecordHTTPResponse(statusCode int) {
+	if statusCode >= http.StatusBadRequest && statusCode < http.StatusInternalServerError+100 {
+		HTTPErrorResponses.Inc()
+	}
+}
+
+// CountHTTPErrors wraps a handler and records each 4xx or 5xx response.
+func CountHTTPErrors(next http.Handler) http.Handler {
+	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		recorder := &statusRecorder{
+			ResponseWriter: w,
+			statusCode:     http.StatusOK,
+		}
+
+		next.ServeHTTP(recorder, r)
+		RecordHTTPResponse(recorder.statusCode)
+	})
+}
+
+type statusRecorder struct {
+	http.ResponseWriter
+	statusCode  int
+	wroteHeader bool
+}
+
+func (r *statusRecorder) WriteHeader(statusCode int) {
+	if r.wroteHeader {
+		return
+	}
+
+	r.wroteHeader = true
+	r.statusCode = statusCode
+	r.ResponseWriter.WriteHeader(statusCode)
+}
+
+func (r *statusRecorder) Write(body []byte) (int, error) {
+	if !r.wroteHeader {
+		r.WriteHeader(http.StatusOK)
+	}
+
+	return r.ResponseWriter.Write(body)
+}
+
+func (r *statusRecorder) Unwrap() http.ResponseWriter {
+	return r.ResponseWriter
+}
