+package gateway
+
+import (
+	"net/http"
+	"net/http/httptest"
+	"testing"
+
+	"lsd-author/internal/metrics"
+)
+
+func TestRecordHTTPResponseCountsOnlyClientAndServerErrors(t *testing.T) {
+	before := HTTPErrorResponses.Value()
+
+	for _, statusCode := range []int{
+		http.StatusOK,
+		http.StatusMultipleChoices,
+		http.StatusBadRequest,
+		http.StatusInternalServerError,
+		599,
+		600,
+	} {
+		RecordHTTPResponse(statusCode)
+	}
+
+	got := HTTPErrorResponses.Value() - before
+	if got != 3 {
+		t.Fatalf("RecordHTTPResponse incremented %d times, want 3", got)
+	}
+}
+
+func TestCountHTTPErrorsCountsHandlerErrorStatus(t *testing.T) {
+	before := HTTPErrorResponses.Value()
+	handler := CountHTTPErrors(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		http.Error(w, "bad request", http.StatusBadRequest)
+	}))
+
+	handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/", nil))
+
+	got := HTTPErrorResponses.Value() - before
+	if got != 1 {
+		t.Fatalf("CountHTTPErrors incremented %d times, want 1", got)
+	}
+}
+
+func TestCountHTTPErrorsUsesFirstWrittenStatus(t *testing.T) {
+	before := HTTPErrorResponses.Value()
+	handler := CountHTTPErrors(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if _, err := w.Write([]byte("ok")); err != nil {
+			t.Fatalf("write response: %v", err)
+		}
+		w.WriteHeader(http.StatusInternalServerError)
+	}))
+
+	handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/", nil))
+
+	got := HTTPErrorResponses.Value() - before
+	if got != 0 {
+		t.Fatalf("CountHTTPErrors incremented %d times, want 0", got)
+	}
+}
+
+func TestGatewayHTTPErrorCounterRegistered(t *testing.T) {
+	counter, ok := metrics.DefaultRegistry.Counter("gateway_http_errors_total")
+	if !ok {
+		t.Fatal("gateway_http_errors_total was not registered")
+	}
+	if counter != HTTPErrorResponses {
+		t.Fatal("gateway_http_errors_total registered a different counter")
+	}
+}
