@@ -0,0 +1,81 @@
+package metrics
+
+import (
+	"fmt"
+	"sync"
+	"sync/atomic"
+)
+
+// Counter is a monotonically increasing metric registered with a Registry.
+type Counter struct {
+	name  string
+	help  string
+	value atomic.Uint64
+}
+
+// Name returns the metric name.
+func (c *Counter) Name() string {
+	return c.name
+}
+
+// Help returns the metric description.
+func (c *Counter) Help() string {
+	return c.help
+}
+
+// Inc increments the counter by one.
+func (c *Counter) Inc() {
+	c.value.Add(1)
+}
+
+// Value returns the current counter value.
+func (c *Counter) Value() uint64 {
+	return c.value.Load()
+}
+
+// Registry stores process metrics by name.
+type Registry struct {
+	mu       sync.RWMutex
+	counters map[string]*Counter
+}
+
+// DefaultRegistry is the process-wide metrics registry.
+var DefaultRegistry = NewRegistry()
+
+// NewRegistry creates an empty metrics registry.
+func NewRegistry() *Registry {
+	return &Registry{
+		counters: make(map[string]*Counter),
+	}
+}
+
+// NewCounter creates a counter and registers it with the default registry.
+func NewCounter(name, help string) *Counter {
+	counter := &Counter{name: name, help: help}
+	DefaultRegistry.MustRegister(counter)
+	return counter
+}
+
+// MustRegister registers a counter or panics if its name is already in use.
+func (r *Registry) MustRegister(counter *Counter) {
+	if counter == nil {
+		panic("metrics: cannot register nil counter")
+	}
+
+	r.mu.Lock()
+	defer r.mu.Unlock()
+
+	if _, exists := r.counters[counter.name]; exists {
+		panic(fmt.Sprintf("metrics: counter %q already registered", counter.name))
+	}
+	r.counters[counter.name] = counter
+}
+
+// Counter returns a registered counter by name.
+func (r *Registry) Counter(name string) (*Counter, bool) {
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+
+	counter, ok := r.counters[name]
+	return counter, ok
+}

