+	attempts     int
+	successAfter int
+}
+
+func (c *testConn) Get(key string) ([]byte, error) {
+	c.attempts++
+	if c.successAfter > 0 && c.attempts >= c.successAfter {
+		return []byte("value:" + key), nil
+	}
+	return nil, errors.New("busy")
+}
+
+type Client struct {
+	conn interface {
+		Get(string) ([]byte, error)
+	}
+}
+
+func TestGetReturnsValueAfterTransientBusyErrors(t *testing.T) {
+	conn := &testConn{successAfter: 6}
+	client := &Client{conn: conn}
+
+	got, err := client.Get("alpha")
+	if err != nil {
+		t.Fatalf("Get returned error: %v", err)
+	}
+	if string(got) != "value:alpha" {
+		t.Fatalf("Get returned %q, want %q", got, "value:alpha")
+	}
+}
+
+func TestGetReturnsUnavailableAfterRetryBudget(t *testing.T) {
+	conn := &testConn{}
+	client := &Client{conn: conn}
+
+	_, err := client.Get("alpha")
+	if !errors.Is(err, ErrUnavailable) {
+		t.Fatalf("Get error = %v, want %v", err, ErrUnavailable)
+	}
+	if conn.attempts != 8 {
+		t.Fatalf("Get attempts = %d, want 8", conn.attempts)
+	}
+}
